// named import: the Nx Playwright plugin loads the config without default-import interop
import {parse} from 'dotenv';
import {existsSync, readFileSync} from 'node:fs';
import * as path from 'node:path';

/*
 * Where the e2e settings come from, highest precedence first:
 *  1. the shell environment
 *  2. e2e.env - local users generated by scripts/provision-local-users.mjs (keys prefixed per tenant, BS_/BE_)
 *  3. .env    - hand-written, see .env-template (unprefixed keys, one tenant)
 *
 * E2E_TENANT (default bs) picks the tenant. A key is looked up with the tenant prefix first, so one e2e.env
 * can hold users for every tenant. Only BS also accepts unprefixed keys: that keeps an existing .env working,
 * and stops its single-tenant users from being tried against another tenant.
 */
const readEnvFile = (file: string): Record<string, string> =>
  existsSync(file) ? parse(readFileSync(file)) : {};

const sources = [
  process.env as Record<string, string | undefined>,
  readEnvFile(path.resolve(__dirname, 'e2e.env')),
  readEnvFile(path.resolve(__dirname, '.env')),
];

export const tenant = (process.env['E2E_TENANT'] || 'bs').toLowerCase();

function setting(name: string): string | undefined {
  const prefixed = `${tenant.toUpperCase()}_${name}`;
  for (const source of sources) {
    const value = source[prefixed] ?? (tenant === 'bs' ? source[name] : undefined);
    if (value) {
      return value;
    }
  }
  return undefined;
}

const user = (envName: string) => ({
  name: setting(`${envName}_USER`),
  password: setting(`${envName}_PASSWORD`),
});

export const testUsers = {
  ESC_ADMIN: user('ESC_ADMIN'),
  ESC_EMPFANG: user('ESC_EMPFANG'),
  ESC_MPA: user('ESC_MPA'),
  ESC_ORTHOPOSTIN: user('ESC_ORTHOPISTIN'),
  ESC_SCHULAERZTIN: user('ESC_SCHULAERZTIN'),
  ESC_SUPERMPA: user('ESC_SUPERMPA'),
  ESC_SUPPORT: user('ESC_SUPPORT'),
};

export type TestUserRole = keyof typeof testUsers;

/** The local docker-compose OAuth2Proxy port per tenant. */
const LOCAL_PORTS: Record<string, number> = {
  bs: 4443,
  win: 5443,
  be: 6443,
};
const localPort = LOCAL_PORTS[tenant] ?? LOCAL_PORTS['bs'];

export const baseURL = setting('BASE_URL') || `https://local-esc-${tenant}.localhost:${localPort}/`;

// The worker processes inherit the environment, so they see the same resolved values as the config.
process.env['E2E_TENANT'] = tenant;
process.env['BASE_URL'] = baseURL;

/**
 * Where a role's login is stored. BS keeps the historical location; other tenants get their own directory,
 * because a storage state only carries cookies for one tenant's host.
 */
export function authStatePath(role: TestUserRole): string {
  return tenant === 'bs' ? `./playwright/.auth/${role}` : `./playwright/.auth/${tenant}/${role}`;
}

export const runId = process.env['RUN_ID'] || 'local';
